        "backDesc": "ระหว่างความสามารถโจมตีของคุณ {FIRE_X} เพื่อเพิ่ม {WOUND.fh} ให้กับการโจมตีหนึ่งครั้ง แล้วพลิกการ์ดนี้เมื่อจบเทิร์นของคุณ"
