        "backDesc": "ระหว่างความสามารถโจมตีประชิดของคุณ {WIND_X} เพื่อเพิ่ม {PUSH.fh} 2 ให้กับการโจมตีหนึ่งครั้ง แล้วพลิกการ์ดนี้"
